import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"Integrated RAG, workflow and n8n practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/applied-ai/index.md","filePath":"practice/applied-ai/index.md"}'),i={name:"practice/applied-ai/index.md"};function o(s,e,d,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="integrated-rag-workflow-and-n8n-practice" tabindex="-1">Integrated RAG, workflow and n8n practice <a class="header-anchor" href="#integrated-rag-workflow-and-n8n-practice" aria-label="Permalink to “Integrated RAG, workflow and n8n practice”">​</a></h1><p><strong>All learner practice remains outstanding.</strong> These specifications refine the existing P-334/P-335 projects and add one bounded n8n integration. Supplied workbench passes are reference verification, not evidence that you implemented or mastered the projects.</p><p>Use one synthetic notes catalogue: tenant <code>study</code>, user <code>alice</code>, note <code>public</code> describing timeout/cancellation; tenant <code>other</code> with a forbidden note; and one instruction-like source line. Reuse the existing <a href="./../ai-lab/README.html">corpus/case seed</a>, reviewed source/version/span records and permission adapters. The seed is development material, not a held-out quality benchmark. Never copy real private notes or credentials into fixtures.</p><table tabindex="0"><thead><tr><th>Sequence</th><th>Deliverable / specification</th><th>Prerequisites</th></tr></thead><tbody><tr><td>1 / P-334</td><td><a href="./rag-assistant.html">Access-aware cited assistant</a></td><td>Typed Python, validation, owned async I/O and shared model/evaluation/security boundaries</td></tr><tr><td>2 / P-335</td><td><a href="./resumable-workflow.html">Resumable approved tool workflow</a></td><td>Checked tools and current identity; a RAG result grants no permission</td></tr><tr><td>3 / N8N-P01</td><td><a href="./n8n-integration.html">Refresh event integration</a></td><td>JSON/HTTP, scoped synthetic service identity and manual/test-only n8n setup</td></tr></tbody></table><p>Start each stage with a pure or local deterministic fixture. A live provider, published workflow, external notification, hosted vector service and paid account are not prerequisites to begin. Any later real integration needs its own authorized credentials/data/budget; do not describe it as tested because a mock passed.</p><h2 id="evidence-for-every-stage" tabindex="-1">Evidence for every stage <a class="header-anchor" href="#evidence-for-every-stage" aria-label="Permalink to “Evidence for every stage”">​</a></h2><p>Retain actual source/lock/runtime, case/corpus/ACL/prompt/model/parser/index/configuration versions; expected versus observed results; failing counterexample and correction; allowed/denied call/effect counts; resource cleanup; and commands with exit results. For recovery record checkpoint revision, artifact references, original operation ID and authoritative receipt or explicit unknown outcome. Exclude raw credentials/private evidence from ordinary logs.</p><p>Separate deterministic schema/access/state/receipt checks from human claim-support judgments and model-quality measurements. Label fake transports/authored proposals as synthetic. Count all attempts, failures, cancellations, waits and known/unknown cost. Record the dataset split/seed/rubric and do not tune on the final confirmation set.</p><p>Use the existing <a href="./../learning-projects.html#retain-a-real-evidence-record">evidence record</a>. Never prefill success. Preserve Autocode template/scripts/database configuration where applicable; never modify <code>src/tests</code>. Relevant builds/type checks/tests must terminate naturally. <a href="./chapters/">Chapter requirements</a> retain the more focused exercises without creating dozens of unrelated projects.</p>',9)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
